def main():
    load_dotenv();store=Store();count=0
    for rid,title,claim,a,b,sub,question,reason in PROPOSALS:
        try:r=store.get(rid)
        except KeyError:continue
        if r['source']['source_id']!='SRC-e209f0cca8a26244':continue
        pattern='تفريق بين متماثلين' if rid=='SHB-0738b1f6e28e' else 'جمع بين مختلفين'
        changes={'title_ar':title,'central_claim_ar':claim,'compared_entities_ar':[{'entity_a':a,'entity_b':b}], 'primary_pattern':pattern,'sub_patterns':[sub] if sub else [],'revealing_question_ar':question,'diagnostic_reason_ar':reason,'treatment_ar':'بيّن وجه التماثل والجمع بينهما' if pattern=='تفريق بين متماثلين' else 'بيّن الفارق المؤثر','response_path_ar':['تحرير الدعوى وحدودها من النص','تحديد الطرفين: '+a+' / '+b,'فحص جهة المقارنة والفارق أو وجه التماثل','مقابلة القاعدة والمقتطف بالصفحة الأصلية','عرض التشخيص على الخبير دون إنشاء حكم على الأشخاص'],'tags':['source_candidate','structured_source_read_proposal'],'confidence':None}
        count+=store.add_machine_proposal(rid,changes,'source_read_analysis_v1')
    export_snapshots(store)
    print({'structured_proposals':count,'human_approvals':0})

if __name__=='__main__':main()
